"""Tool-interface continuity and the split acceptance result. The golden file is generated by the JS SDK
(sdk/test/fixtures/continuity-gen.mjs); this SDK must reproduce every record field for field, record_sha256 included."""
import json
import os
import unittest

from crawlcheck.continuity import (CONTINUITY_FAILURE_CLASSES, acceptance_of, continuity_check, continuity_failure,
                                   continuity_policy, lock_parts)
from crawlcheck.lock import lock_from_tools

G = json.load(open(os.path.join(os.path.dirname(__file__), "fixtures", "continuity.json"), encoding="utf-8"))


def _kw(o):
    m = {"mode": "mode", "policy": "policy", "exceptions": "exceptions", "complete": "complete", "server": "server",
         "serverIdentity": "server_identity", "expectPolicySha256": "expect_policy_sha256", "now": "now"}
    return {m[k]: v for k, v in o.items() if k in m}


class Golden(unittest.TestCase):
    def test_default_policy_hash(self):
        self.assertEqual(continuity_policy()["sha256"], G["default_policy_sha256"])

    def test_lock_and_parts(self):
        self.assertEqual(lock_from_tools(G["tools_v1"])["tools_sha256"], G["lock"]["tools_sha256"])
        self.assertEqual(lock_parts(G["tools_v1"]), G["lock"]["parts"])

    def test_cases(self):
        for c in G["cases"]:
            with self.subTest(c["name"]):
                self.assertEqual(continuity_check(c["lock"], c["tools"], **_kw(c["opts"])), c["expect"])

    def test_failures(self):
        self.assertEqual(len(G["failures"]), len(CONTINUITY_FAILURE_CLASSES) * 3)
        for f in G["failures"]:
            with self.subTest(f["cls"] + " " + f["opts"]["mode"]):
                o = _kw(f["opts"])
                self.assertEqual(continuity_failure(f["cls"], mode=o["mode"], server=o.get("server"), now=o["now"]), f["expect"])

    def test_acceptance(self):
        for a in G["acceptance"]:
            with self.subTest(a["name"]):
                o = a["opts"]
                self.assertEqual(acceptance_of(a["receipt"], a["verification"], a["scope"], allow_warn=bool(o.get("allowWarn")), confirmed=o.get("confirmed")), a["expect"])

    def test_integrity_cannot_be_loosened_silently(self):
        with self.assertRaises(ValueError):
            continuity_policy({"effects": {"signature_invalid": "proceed"}})
        self.assertTrue(continuity_policy({"effects": {"signature_invalid": "pause"}, "allow_integrity_override": True})["allow_integrity_override"])


if __name__ == "__main__":
    unittest.main()
